 $('[data-progress-count]').textContent=count+' of '+total+' checks';$('[data-progress-percent]').textContent=Math.round(count/total*100)+'%';$('[data-progress-fill]').style.width=count/total*100+'%';$('[data-progress-fraction]').textContent=count+' / '+total;
 $$('[data-check-status]').forEach(el=>el.textContent=completed.has(el.dataset.checkStatus)?'Required check completed':'Check not completed');
